CREATE TABLE "cjays_customers" ("id" TEXT NOT NULL,"tenant_id" TEXT NOT NULL,"client_id" TEXT NOT NULL,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT NOT NULL DEFAULT '',"server_version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "cjays_customers_pkey" PRIMARY KEY ("id"),CONSTRAINT "cjays_customers_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "cjays_customers_tenant_id_client_id_key" ON "cjays_customers"("tenant_id","client_id");
CREATE INDEX "cjays_customers_tenant_id_phone_idx" ON "cjays_customers"("tenant_id","phone");
CREATE TABLE "cjays_vehicles" ("id" TEXT NOT NULL,"tenant_id" TEXT NOT NULL,"client_id" TEXT NOT NULL,"customer_client_id" TEXT,"vin" TEXT NOT NULL,"year" TEXT NOT NULL DEFAULT '',"make" TEXT NOT NULL DEFAULT '',"model" TEXT NOT NULL DEFAULT '',"color" TEXT NOT NULL DEFAULT '',"server_version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "cjays_vehicles_pkey" PRIMARY KEY ("id"),CONSTRAINT "cjays_vehicles_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "cjays_vehicles_tenant_id_client_id_key" ON "cjays_vehicles"("tenant_id","client_id");
CREATE UNIQUE INDEX "cjays_vehicles_tenant_id_vin_key" ON "cjays_vehicles"("tenant_id","vin");
CREATE TABLE "cjays_jobs" ("id" TEXT NOT NULL,"tenant_id" TEXT NOT NULL,"client_id" TEXT NOT NULL,"vehicle_client_id" TEXT NOT NULL,"service" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'In Progress',"price" TEXT NOT NULL DEFAULT '',"checklist" JSONB NOT NULL DEFAULT '[]',"notes" TEXT NOT NULL DEFAULT '',"payment_method" TEXT NOT NULL DEFAULT '',"paid_amount" TEXT NOT NULL DEFAULT '',"before_photos" JSONB NOT NULL DEFAULT '[]',"after_photos" JSONB NOT NULL DEFAULT '[]',"server_version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "cjays_jobs_pkey" PRIMARY KEY ("id"),CONSTRAINT "cjays_jobs_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "cjays_jobs_tenant_id_client_id_key" ON "cjays_jobs"("tenant_id","client_id");
CREATE INDEX "cjays_jobs_tenant_id_status_idx" ON "cjays_jobs"("tenant_id","status");
CREATE TABLE "cjays_sync_events" ("id" TEXT NOT NULL,"tenant_id" TEXT NOT NULL,"request_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"record_counts" JSONB NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "cjays_sync_events_pkey" PRIMARY KEY ("id"),CONSTRAINT "cjays_sync_events_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "cjays_sync_events_tenant_id_request_id_key" ON "cjays_sync_events"("tenant_id","request_id");
CREATE INDEX "cjays_sync_events_tenant_id_created_at_idx" ON "cjays_sync_events"("tenant_id","created_at");
